/**
 * Minimal markdown → HTML for resume rendering.
 *
 * Supports the subset this toolkit produces: `#`/`##`/`###` headings,
 * `-` bullets, `**bold**`, paragraphs, blank lines. Deliberately small —
 * resumes are generated by our own flows, not arbitrary markdown.
 */

export function escapeHtml(text: string): string {
  return text
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
}

function inline(text: string): string {
  return escapeHtml(text).replace(/\*\*([^*]+)\*\*/g, "<strong>$1</strong>")
}

export function markdownToHtml(markdown: string): string {
  const out: string[] = []
  let inList = false
  const closeList = (): void => {
    if (inList) {
      out.push("</ul>")
      inList = false
    }
  }
  for (const line of markdown.split(/\r?\n/)) {
    const trimmed = line.trim()
    if (trimmed === "") {
      closeList()
      continue
    }
    const heading = trimmed.match(/^(#{1,3})\s+(.*)$/)
    if (heading) {
      closeList()
      const level = heading[1]?.length ?? 1
      out.push(`<h${level}>${inline(heading[2] ?? "")}</h${level}>`)
      continue
    }
    const bullet = trimmed.match(/^[-*]\s+(.*)$/)
    if (bullet) {
      if (!inList) {
        out.push("<ul>")
        inList = true
      }
      out.push(`<li>${inline(bullet[1] ?? "")}</li>`)
      continue
    }
    closeList()
    out.push(`<p>${inline(trimmed)}</p>`)
  }
  closeList()
  return out.join("\n")
}

/** ATS-safe single-column resume document. */
export function buildResumeHtml(markdown: string, title: string): string {
  return `<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<title>${escapeHtml(title)}</title>
<style>
  body { font-family: -apple-system, "Segoe UI", Roboto, Helvetica, Arial, sans-serif; color: #111; margin: 0; font-size: 11pt; line-height: 1.45; }
  html { font-variant-ligatures: none; font-feature-settings: "liga" 0, "clig" 0; }
  main { max-width: 720px; margin: 0 auto; padding: 32px 24px; }
  h1 { font-size: 20pt; margin: 0 0 4px; }
  h2 { font-size: 13pt; margin: 18px 0 6px; border-bottom: 1px solid #ddd; padding-bottom: 2px; }
  h3 { font-size: 11.5pt; margin: 12px 0 4px; }
  ul { margin: 4px 0 8px; padding-left: 18px; }
  li { margin: 2px 0; }
  p { margin: 4px 0; }
  @page { margin: 18mm 16mm; }
</style>
</head>
<body>
<main>
${markdownToHtml(markdown)}
</main>
</body>
</html>
`
}
